CREATE TABLE public.business_revisions (user_id uuid PRIMARY KEY, revision integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.business_revisions TO authenticated; GRANT ALL ON public.business_revisions TO service_role;
ALTER TABLE public.business_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_revision ON public.business_revisions FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE TABLE public.materials (id text NOT NULL, user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, unit text NOT NULL, quantity numeric NOT NULL DEFAULT 0, minimum numeric NOT NULL DEFAULT 0, "unitCost" numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.materials TO authenticated; GRANT ALL ON public.materials TO service_role;
ALTER TABLE public.materials ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_materials ON public.materials FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE TABLE public.stock_movements (id text NOT NULL, user_id uuid NOT NULL DEFAULT auth.uid(), "materialId" text NOT NULL, kind text NOT NULL, quantity numeric NOT NULL, note text NOT NULL DEFAULT '', "createdAt" timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,id), FOREIGN KEY(user_id,"materialId") REFERENCES public.materials(user_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.stock_movements TO authenticated; GRANT ALL ON public.stock_movements TO service_role;
ALTER TABLE public.stock_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_movements ON public.stock_movements FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE TABLE public.products (id text NOT NULL, user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, "batchYield" numeric NOT NULL, recipe jsonb NOT NULL DEFAULT '[]', "producedUnits" numeric NOT NULL DEFAULT 0, "createdAt" timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_products ON public.products FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE TABLE public.productions (id text NOT NULL, user_id uuid NOT NULL DEFAULT auth.uid(), "productId" text NOT NULL, batches numeric NOT NULL, units numeric NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,id), FOREIGN KEY(user_id,"productId") REFERENCES public.products(user_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.productions TO authenticated; GRANT ALL ON public.productions TO service_role;
ALTER TABLE public.productions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_productions ON public.productions FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE TABLE public.sales (id text NOT NULL, user_id uuid NOT NULL DEFAULT auth.uid(), "productId" text NOT NULL, quantity numeric NOT NULL, "unitPrice" numeric NOT NULL, "unitCost" numeric NOT NULL, "soldAt" timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,id), FOREIGN KEY(user_id,"productId") REFERENCES public.products(user_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sales TO authenticated; GRANT ALL ON public.sales TO service_role;
ALTER TABLE public.sales ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_sales ON public.sales FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE TABLE public.expenses (id text NOT NULL, user_id uuid NOT NULL DEFAULT auth.uid(), description text NOT NULL, category text NOT NULL, amount numeric NOT NULL, "spentAt" date NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.expenses TO authenticated; GRANT ALL ON public.expenses TO service_role;
