CREATE TABLE public.product_prices (user_id uuid NOT NULL DEFAULT auth.uid(), "productId" text NOT NULL, price numeric NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,"productId"), FOREIGN KEY(user_id,"productId") REFERENCES public.products(user_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_prices TO authenticated; GRANT ALL ON public.product_prices TO service_role;
ALTER TABLE public.product_prices ENABLE ROW LEVEL SECURITY;
