CREATE FUNCTION public.touch_business_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
CREATE TRIGGER touch_revision BEFORE UPDATE ON public.business_revisions FOR EACH ROW EXECUTE FUNCTION public.touch_business_updated_at();
CREATE TRIGGER touch_material BEFORE UPDATE ON public.materials FOR EACH ROW EXECUTE FUNCTION public.touch_business_updated_at();
CREATE TRIGGER touch_movement BEFORE UPDATE ON public.stock_movements FOR EACH ROW EXECUTE FUNCTION public.touch_business_updated_at();
CREATE TRIGGER touch_product BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.touch_business_updated_at();
CREATE TRIGGER touch_production BEFORE UPDATE ON public.productions FOR EACH ROW EXECUTE FUNCTION public.touch_business_updated_at();
CREATE TRIGGER touch_sale BEFORE UPDATE ON public.sales FOR EACH ROW EXECUTE FUNCTION public.touch_business_updated_at();
CREATE TRIGGER touch_expense BEFORE UPDATE ON public.expenses FOR EACH ROW EXECUTE FUNCTION public.touch_business_updated_at();
CREATE TRIGGER touch_price BEFORE UPDATE ON public.product_prices FOR EACH ROW EXECUTE FUNCTION public.touch_business_updated_at();
CREATE FUNCTION public.read_business_data() RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE u uuid := auth.uid(); result jsonb;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
 INSERT INTO public.business_revisions(user_id) VALUES(u) ON CONFLICT DO NOTHING;
 PERFORM revision FROM public.business_revisions WHERE user_id=u FOR SHARE;
 SELECT jsonb_build_object('revision',r.revision,'materials',COALESCE((SELECT jsonb_agg(to_jsonb(t)-'user_id'-'created_at'-'updated_at') FROM public.materials t WHERE user_id=u),'[]'::jsonb),'movements',COALESCE((SELECT jsonb_agg(to_jsonb(t)-'user_id'-'created_at'-'updated_at') FROM public.stock_movements t WHERE user_id=u),'[]'::jsonb),'products',COALESCE((SELECT jsonb_agg(to_jsonb(t)-'user_id'-'created_at'-'updated_at') FROM public.products t WHERE user_id=u),'[]'::jsonb),'productions',COALESCE((SELECT jsonb_agg(to_jsonb(t)-'user_id'-'created_at'-'updated_at') FROM public.productions t WHERE user_id=u),'[]'::jsonb),'sales',COALESCE((SELECT jsonb_agg(to_jsonb(t)-'user_id'-'created_at'-'updated_at') FROM public.sales t WHERE user_id=u),'[]'::jsonb),'expenses',COALESCE((SELECT jsonb_agg(to_jsonb(t)-'user_id'-'created_at'-'updated_at') FROM public.expenses t WHERE user_id=u),'[]'::jsonb),'prices',COALESCE((SELECT jsonb_object_agg("productId",price) FROM public.product_prices WHERE user_id=u),'{}'::jsonb)) INTO result FROM public.business_revisions r WHERE user_id=u;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.read_business_data() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.read_business_data() TO authenticated;
CREATE FUNCTION public.save_business_data(expected_revision integer, payload jsonb) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE u uuid := auth.uid(); current_revision integer;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
 INSERT INTO public.business_revisions(user_id) VALUES(u) ON CONFLICT DO NOTHING;
 SELECT revision INTO current_revision FROM public.business_revisions WHERE user_id=u FOR UPDATE;
 IF current_revision <> expected_revision THEN RAISE EXCEPTION 'STALE_REVISION'; END IF;
 DELETE FROM public.product_prices WHERE user_id=u;
 DELETE FROM public.sales WHERE user_id=u;
 DELETE FROM public.productions WHERE user_id=u;
 DELETE FROM public.stock_movements WHERE user_id=u;
 DELETE FROM public.products WHERE user_id=u;
 DELETE FROM public.materials WHERE user_id=u;
 DELETE FROM public.expenses WHERE user_id=u;
 INSERT INTO public.materials(id,user_id,name,unit,quantity,minimum,"unitCost") SELECT id,u,name,unit,quantity,minimum,"unitCost" FROM jsonb_to_recordset(payload->'materials') AS x(id text,name text,unit text,quantity numeric,minimum numeric,"unitCost" numeric);
 INSERT INTO public.products(id,user_id,name,"batchYield",recipe,"producedUnits","createdAt") SELECT id,u,name,"batchYield",recipe,"producedUnits","createdAt" FROM jsonb_to_recordset(payload->'products') AS x(id text,name text,"batchYield" numeric,recipe jsonb,"producedUnits" numeric,"createdAt" timestamptz);
 INSERT INTO public.stock_movements(id,user_id,"materialId",kind,quantity,note,"createdAt") SELECT id,u,"materialId",kind,quantity,note,"createdAt" FROM jsonb_to_recordset(payload->'movements') AS x(id text,"materialId" text,kind text,quantity numeric,note text,"createdAt" timestamptz);
 INSERT INTO public.productions(id,user_id,"productId",batches,units,"createdAt") SELECT id,u,"productId",batches,units,"createdAt" FROM jsonb_to_recordset(payload->'productions') AS x(id text,"productId" text,batches numeric,units numeric,"createdAt" timestamptz);
 INSERT INTO public.sales(id,user_id,"productId",quantity,"unitPrice","unitCost","soldAt") SELECT id,u,"productId",quantity,"unitPrice","unitCost","soldAt" FROM jsonb_to_recordset(payload->'sales') AS x(id text,"productId" text,quantity numeric,"unitPrice" numeric,"unitCost" numeric,"soldAt" timestamptz);
 INSERT INTO public.expenses(id,user_id,description,category,amount,"spentAt") SELECT id,u,description,category,amount,"spentAt" FROM jsonb_to_recordset(payload->'expenses') AS x(id text,description text,category text,amount numeric,"spentAt" date);
 INSERT INTO public.product_prices(user_id,"productId",price) SELECT u,key,value::numeric FROM jsonb_each_text(payload->'prices');
 UPDATE public.business_revisions SET revision=revision+1 WHERE user_id=u RETURNING revision INTO current_revision;
 RETURN current_revision;
END $$;
REVOKE ALL ON FUNCTION public.save_business_data(integer,jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_business_data(integer,jsonb) TO authenticated;